/**
 * The search query language (ADR 0007), shared verbatim by server and client.
 *
 * There is exactly one parser: the dialog uses it to say what it understood
 * and `SearchService` uses it to decide what is searched, so the two cannot
 * disagree. It is pure — no React, no database — which is what lets both
 * sides import it.
 *
 * - Without `advanced_search` the whole query is free text; a colon is just a
 *   character.
 * - With it, a word of the form `field:value` is a field token. `kind:` (also
 *   spelled `in:`, trailing `s` tolerated) and `project:` narrow the search;
 *   every other token, and one with an empty value, is dropped and ignored.
 */
import type { ProjectId } from "@/types/common";

export type SearchSubjectKind = "issue" | "comment" | "project";

export const SEARCH_SUBJECT_KINDS: readonly SearchSubjectKind[] = [
  "issue",
  "comment",
  "project",
];

/** What is searched when neither the query nor the caller names a kind. */
export const DEFAULT_SEARCH_KINDS: readonly SearchSubjectKind[] = ["issue"];

/** The tokens exactly as typed: `kinds` is empty when no `kind:` token was. */
export interface SearchQueryTokens {
  /** The free-text remainder, with every field token removed. */
  readonly text: string;
  /** The kinds named by `kind:` / `in:` tokens, in the order typed. */
  readonly kinds: readonly SearchSubjectKind[];
  readonly projectId: ProjectId | null;
  /** Tokens that looked like syntax but named nothing we know. */
  readonly unknownTokens: readonly string[];
}

export interface ParsedSearchQuery {
  /** The free-text remainder, with every recognised token removed. */
  readonly text: string;
  readonly kinds: readonly SearchSubjectKind[];
  readonly projectId: ProjectId | null;
  /** Tokens that looked like syntax but named nothing we know. */
  readonly unknownTokens: readonly string[];
}

/**
 * Splits a query into its field tokens and its free text.
 *
 * @param raw      what the user typed
 * @param advanced whether the `advanced_search` flag is on for this org; when
 *                 false the whole string is free text so a colon in a title
 *                 still finds the title.
 */
export function readSearchQueryTokens(
  raw: string,
  advanced: boolean,
): SearchQueryTokens {
  if (!advanced) {
    return { text: raw.trim(), kinds: [], projectId: null, unknownTokens: [] };
  }

  const terms: string[] = [];
  const kinds: SearchSubjectKind[] = [];
  const unknown: string[] = [];
  let projectId: ProjectId | null = null;

  for (const token of raw.split(/\s+/).filter((part) => part.length > 0)) {
    const separator = token.indexOf(":");
    if (separator <= 0) {
      terms.push(token);
      continue;
    }

    const field = token.slice(0, separator).toLowerCase();
    const value = token.slice(separator + 1);
    if (value.length === 0) {
      unknown.push(token);
      continue;
    }

    if (field === "kind" || field === "in") {
      const kind = toKind(value);
      if (kind !== null) kinds.push(kind);
      else unknown.push(token);
    } else if (field === "project") {
      projectId = value as ProjectId;
    } else {
      unknown.push(token);
    }
  }

  return {
    text: terms.join(" "),
    kinds,
    projectId,
    unknownTokens: unknown,
  };
}

/**
 * The query as the dialog presents it: the tokens of
 * `readSearchQueryTokens()`, with the default kind filled in when the query
 * names none.
 */
export function parseSearchQuery(
  raw: string,
  advanced: boolean,
): ParsedSearchQuery {
  const tokens = readSearchQueryTokens(raw, advanced);
  return {
    text: tokens.text,
    kinds: tokens.kinds.length > 0 ? tokens.kinds : DEFAULT_SEARCH_KINDS,
    projectId: tokens.projectId,
    unknownTokens: tokens.unknownTokens,
  };
}

/** A one-line explanation of what the parser understood, for the dialog. */
export function describeQuery(parsed: ParsedSearchQuery): string {
  const parts = [`searching ${parsed.kinds.join(", ")}`];
  if (parsed.projectId !== null) parts.push(`in project ${parsed.projectId}`);
  if (parsed.unknownTokens.length > 0) {
    parts.push(`ignoring ${parsed.unknownTokens.join(", ")}`);
  }
  return parts.join(" · ");
}

/** `comment`, `Comments`, `COMMENT` → `comment`; anything else → `null`. */
function toKind(value: string): SearchSubjectKind | null {
  const lowered = value.toLowerCase();
  for (const candidate of [lowered, lowered.replace(/s$/, "")]) {
    const kind = SEARCH_SUBJECT_KINDS.find((known) => known === candidate);
    if (kind !== undefined) return kind;
  }
  return null;
}

