    expect(hits.total).toBe(1);
    expect(hits.items[0]?.id).toBe(issue.id);
    expect((await q(starter, "kind:comment hotfix")).total).toBe(0);
  });

  it("2/3: tokens narrow on enterprise, comments carry project", async () => {
    const issue = await issueService.createIssue(ent.actors.member, issueInput(ent.org.id, ent.project.id, { title: "Deploy pipeline" }));
