    // project: overrides caller's projectId
    expect((await q(ent, `project:${ent.project.id} deploy`, { projectId: "other" })).total).toBe(1);
    // projectId filter finds comments
    const byFilter = await q(ent, "flaky", { kinds: ["comment"], projectId: ent.project.id });
    expect(byFilter.total).toBe(1);
