/** Token bucket protecting the index from query bursts. */
const SEARCH_QUERY_BUCKET = "search:query";

/**
 * Runs a query against the denormalised index, as ADR 0007 specifies. This is
 * the gate: the entry points above pass the query and the requested kinds
 * through untouched.
 *
 * - Without `advanced_search` the whole query is literal free text (a colon
 *   is just a character, and no query is refused for its syntax) and only
 *   issues are searched, whatever kinds the caller asked for.
 * - With it, the query is read by the same parser the dialog uses: `kind:`
 *   tokens decide the kinds and `project:` the project, overriding the
 *   caller's `kinds` / `projectId`; what remains is the free text.
 */
export async function search(
  actor: Actor,
  input: SearchQueryInput,
): Promise<Page<SearchHit>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));

  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Search rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await orgRepo.findOrgById(input.orgId);
  const advanced = isEnabled("advanced_search", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  const tokens = readSearchQueryTokens(input.q, advanced);
  const text = tokens.text;
  const projectId = tokens.projectId ?? input.projectId;

  const page = await searchRepo.searchDocuments({
    ...input,
    q: text,
    kinds: resolveKinds(advanced, tokens.kinds, input.kinds),
    projectId,
  });

  return {
    items: page.items.map((row) => ({
      kind: row.subjectKind,
      id: row.subjectId,
      title: row.content.split("\n")[0] ?? row.subjectId,
      snippet: snippetAround(row.content, text),
      href: hrefFor(row.subjectKind, row.subjectId),

